# typed: strict
# frozen_string_literal: true

require "github/packwerk/privacy/violations_against_packages"

module GitHub
  module Packwerk
    module Privacy
      class PrivacyViolationTodos
        PRIVACY_TODO_FILENAME = "privacy_todo.yml"
        PRIVACY_TODO_HEADER = <<-HEADER
# Note: this file is autogenerated. Run `bin/packwerk update-todo` to update this file.
#
# Packwerk privacy violations against this package are listed here so that CODEOWNERS will notify
# the package's owning team of any changes to privacy violations.
#
HEADER

        class ConsistencyError < StandardError; end

        sig { void }
        def self.check!
          new.check!
        end

        sig { void }
        def self.persist!
          new.persist!
        end

        sig { returns(ViolationsAgainstPackages) }
        attr_reader :violations_collection

        sig { void }
        def initialize
          @violations_collection = T.let(ViolationsAgainstPackages.new, ViolationsAgainstPackages)
        end

        sig { void }
        def check!
          # all existing privacy_todo.yml files are accurate
          violations_from_package_todos.each do |package_name, _violations|
            file_path = privacy_todo_filepath(package_name)

            if violations_from_package_todos[package_name]
              expected_file_contents = PRIVACY_TODO_HEADER + violations_from_package_todos[package_name].to_h.to_yaml
              raise_consistency_error(file_path) unless File.exist?(file_path)
              actual_file_contents = File.read(file_path)
              raise_consistency_error(file_path) unless expected_file_contents == actual_file_contents
            end
          end

          # no stale privacy_todo.yml files remain
          violations_collection.packwerk_packages.each do |package|
            next if violations_from_package_todos.key?(package.name)

            file_path = privacy_todo_filepath(package.name)
            raise_consistency_error(file_path) if File.exist?(file_path)
          end
        end

        sig { void }
        def persist!
          violations_from_package_todos.each do |package_name, _violations|
            file_path = privacy_todo_filepath(package_name)
            file_contents = violations_from_package_todos[package_name].to_h.to_yaml
            File.write(file_path, PRIVACY_TODO_HEADER + file_contents, mode: "w+")
          end

          violations_collection.packwerk_packages.each do |package|
            next if violations_from_package_todos.key?(package.name)

            file_path = privacy_todo_filepath(package.name)
            File.delete(file_path) if File.exist?(file_path)
          end
        end

        sig { returns(T::Array[Pathname]) }
        def privacy_todo_file_paths
          violations_collection.packwerk_todos.map { |todo| todo.pathname.dirname.join(PRIVACY_TODO_FILENAME) }
        end

        private

        sig { returns(T::Hash[String, ViolationsAgainstPackage]) }
        def violations_from_package_todos
          violations_collection.all_violations
        end

        sig { params(package_name: String).returns(Pathname) }
        def privacy_todo_filepath(package_name)
          Pathname.new(
            File.join(package_name, PRIVACY_TODO_FILENAME)
          ).cleanpath
        end

        sig { params(file_path: Pathname).void }
        def raise_consistency_error(file_path)
          raise ConsistencyError, "Discrepancy detected in #{file_path}. Run `bin/packwerk update` to fix."
        end
      end
    end
  end
end
